arguments.command:
# Search broader
grep -i 'factory\|Create.*Function' /home/runner/.nuget/packages/microsoft.extensions.ai/10.6.0/lib/net10.0/Microsoft.Extensions.AI.xml | head -20
echo "==="
# Maybe AIFunction.Create is directly in abstractions - let me check the DLL with reflection
cat > /tmp/check_api.csx << 'EOF'
using System.Reflection;
var asm = Assembly.LoadFrom("/home/runner/.nuget/packages/microsoft.extensions.ai.abstractions/10.6.0/lib/net10.0/Microsoft.Extensions.AI.Abstractions.dll");
foreach (var t in asm.GetExportedTypes().Where(t => t.Name.Contains("AIFunction") && !t.Name.Contains("Arguments")))
{
    Console.WriteLine($"=== {t.FullName} ===");
    foreach (var m in t.GetMethods(BindingFlags.Public | BindingFlags.Static | BindingFlags.Instance | BindingFlags.DeclaredOnly))
        Console.WriteLine($"  {(m.IsStatic ? "static " : "")}{m.ReturnType.Name} {m.Name}({string.Join(", ", m.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"))})");
}
EOF
# Can't use csx directly. Let me write a quick program
cd /tmp && mkdir -p checkapi && cat > checkapi/checkapi.csproj << 'EOF'
<Project Sdk="Microsoft.NET.Sdk">
  <PropertyGroup>
    <TargetFramework>net10.0</TargetFramework>
    <OutputType>Exe</OutputType>
  </PropertyGroup>
  <ItemGroup>
    <PackageReference Include="Microsoft.Extensions.AI" Version="10.6.0" />
    <PackageReference Include="Microsoft.Agents.AI" Version="1.*-*" />
  </ItemGroup>
</Project>
EOF
cat > checkapi/Program.cs << 'CEOF'
using System.Reflection;

var asmPath = typeof(Microsoft.Extensions.AI.AIFunction).Assembly;
foreach (var t in asmPath.GetExportedTypes().Where(t => t.Name == "AIFunction"))
{
    Console.WriteLine($"=== {t.FullName} ===");
    foreach (var m in t.GetMethods(BindingFlags.Public | BindingFlags.Static | BindingFlags.DeclaredOnly))
        Console.WriteLine($"  static {m.ReturnType.Name} {m.Name}({string.Join(", ", m.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"))})");
    foreach (var p in t.GetProperties())
        Console.WriteLine($"  prop {p.PropertyType.Name} {p.Name}");
}

Console.WriteLine("\n=== AgentResponse ===");
var art = typeof(Microsoft.Agents.AI.ChatClientAgent).Assembly;
foreach (var t in art.GetExportedTypes().Where(t => t.Name == "AgentResponse"))
{
    foreach (var p in t.GetProperties())
        Console.WriteLine($"  prop {p.PropertyType.Name} {p.Name}");
}
CEOF
