using System;
using System.Linq;
using System.Reflection;

var art = typeof(Microsoft.Agents.AI.ChatClientAgent).Assembly;

// AgentResponse - might be a struct or have different visibility
Console.WriteLine("=== All types containing 'Response' ===");
foreach (var t in art.GetExportedTypes().Where(t => t.Name.Contains("Response")))
    Console.WriteLine($"  {t.FullName} (IsClass={t.IsClass}, IsValueType={t.IsValueType})");

// Check base class methods
Console.WriteLine("\n=== AIAgent base methods ===");
var baseType = typeof(Microsoft.Agents.AI.ChatClientAgent).BaseType;
Console.WriteLine($"Base: {baseType?.FullName}");
if (baseType != null)
{
    foreach (var p in baseType.GetProperties(BindingFlags.Public | BindingFlags.Instance))
        Console.WriteLine($"  prop {p.PropertyType.Name} {p.Name}");
}

// AgentResponse check the return type
Console.WriteLine("\n=== RunAsync return type ===");
var runMethod = typeof(Microsoft.Agents.AI.ChatClientAgent).GetMethod("RunAsync", new[] { typeof(string), typeof(Microsoft.Agents.AI.AgentSession), typeof(Microsoft.Agents.AI.ChatClientAgentRunOptions), typeof(System.Threading.CancellationToken) });
Console.WriteLine($"  Return: {runMethod?.ReturnType.FullName}");
if (runMethod != null)
{
    var retType = runMethod.ReturnType.GenericTypeArguments.FirstOrDefault();
    Console.WriteLine($"  Generic arg: {retType?.FullName}");
    if (retType != null)
    {
        foreach (var p in retType.GetProperties())
            Console.WriteLine($"    prop {p.PropertyType.Name} {p.Name}");
    }
