using System.ComponentModel;
using System.Text;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// --- Build the IChatClient via MEAI abstraction ---
var openAiClient = new OpenAIClient(apiKey);
IChatClient chatClient = openAiClient
    .GetChatClient(modelId)
    .AsIChatClient();

// --- Tool implementations ---
var notebook = new ResearchNotebook();

var tools = new AITool[]
{
    AIFunctionFactory.Create(
        ([Description("The search query to look up on the web")] string query) =>
        {
            Console.ForegroundColor = ConsoleColor.DarkGray;
            Console.WriteLine($"  🔍 Searching: \"{query}\"");
            Console.ResetColor();
            return WebSearchTool.SearchAsync(query);
        },
        "web_search",
        "Searches the web for information about a topic and returns a list of result snippets. " +
        "Use this to gather facts before taking notes."),

    AIFunctionFactory.Create(
        (
            [Description("A short title for this note")] string title,
            [Description("The detailed content of the note")] string content
        ) =>
        {
            notebook.AddNote(title, content);
            Console.ForegroundColor = ConsoleColor.DarkGray;
            Console.WriteLine($"  📝 Note saved: \"{title}\"");
            Console.ResetColor();
            return $"Note '{title}' saved successfully.";
        },
        "save_note",
        "Saves a research note with a title and content. " +
        "Use this to record important findings from your research."),

    AIFunctionFactory.Create(
        () =>
        {
            var notes = notebook.GetAllNotes();
            return notes.Length == 0
                ? "No notes have been saved yet."
                : string.Join("\n\n", notes.Select((n, i) => $"[{i + 1}] {n.Title}\n{n.Content}"));
        },
        "read_notes",
        "Retrieves all previously saved research notes. " +
        "Use this to review what you have learned so far before writing a summary."),
};

// --- Build the agent ---
const string instructions = """
    You are a research agent. When given a topic:
    1. Search the web multiple times to gather diverse information.
    2. Save important findings as notes using the save_note tool.
    3. Review your notes using read_notes.
    4. Provide a comprehensive summary of your research to the user.

    Be thorough — perform at least 2-3 searches from different angles before summarizing.
    Always save key findings as notes before producing the final summary.
    """;

var agent = new ChatClientAgent(
    chatClient,
    instructions: instructions,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and taking notes.",
    tools: tools);

var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
});

// --- Interactive loop ---
Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║         🔬 Research Agent                ║");
Console.WriteLine("║  Enter a topic to research, or 'quit'.   ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("Research topic> ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    Console.WriteLine();
    Console.ForegroundColor = ConsoleColor.Yellow;
    Console.WriteLine($"Researching: {topic}");
    Console.ResetColor();
    Console.WriteLine();

    try
    {
        notebook.Clear();
        var session = await agent.CreateSessionAsync();
        var response = await agent.RunAsync(
            $"Research the following topic and provide a detailed summary: {topic}",
            session,
            runOptions);

        Console.WriteLine();
        Console.ForegroundColor = ConsoleColor.Green;
        Console.WriteLine("═══ Research Summary ═══");
        Console.ResetColor();
        Console.WriteLine(response.Text);
        Console.WriteLine();

        if (notebook.GetAllNotes().Length > 0)
        {
            Console.ForegroundColor = ConsoleColor.DarkYellow;
            Console.WriteLine($"({notebook.GetAllNotes().Length} note(s) collected during research)");
            Console.ResetColor();
            Console.WriteLine();
        }
    }
    catch (Exception ex)
    {
        Console.ForegroundColor = ConsoleColor.Red;
        Console.WriteLine($"Error: {ex.Message}");
        Console.ResetColor();
        Console.WriteLine();
    }
}

Console.WriteLine("Goodbye!");

// --- Supporting types ---

/// <summary>Simulated web search tool that fetches real results via a search API or returns illustrative data.</summary>
static class WebSearchTool
{
    private static readonly HttpClient s_httpClient = new();

    public static async Task<string> SearchAsync(string query)
    {
        // Try using a real web search via DuckDuckGo Instant Answer API (no key required).
        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var json = await s_httpClient.GetStringAsync(url);

            var doc = System.Text.Json.JsonDocument.Parse(json);
            var results = new StringBuilder();

            var abstractText = doc.RootElement.GetProperty("AbstractText").GetString();
            var abstractSource = doc.RootElement.GetProperty("AbstractSource").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                results.AppendLine($"Source: {abstractSource}");
                results.AppendLine(abstractText);
                results.AppendLine();
            }

            if (doc.RootElement.TryGetProperty("RelatedTopics", out var topics))
            {
                var count = 0;
                foreach (var item in topics.EnumerateArray())
                {
                    if (count >= 5) break;
                    var text = item.TryGetProperty("Text", out var t) ? t.GetString() : null;
                    if (!string.IsNullOrWhiteSpace(text))
                    {
                        results.AppendLine($"- {text}");
                        count++;
                    }
                }
            }

            if (results.Length > 0)
                return results.ToString();
        }
        catch
        {
            // Fall through to fallback
        }

        return $"Search results for '{query}': No detailed results available from the web API. " +
               "Please synthesize information based on your training knowledge about this topic.";
    }
}

/// <summary>Thread-safe notebook for storing research notes.</summary>
sealed class ResearchNotebook
{
    private readonly List<(string Title, string Content)> _notes = [];
    private readonly Lock _lock = new();

    public void AddNote(string title, string content)
    {
        lock (_lock)
        {
            _notes.Add((title, content));
        }
    }

    public (string Title, string Content)[] GetAllNotes()
    {
        lock (_lock)
        {
            return [.. _notes];
        }
    }

    public void Clear()
    {
        lock (_lock)
        {
            _notes.Clear();
        }
    }
}

