+                ? "No notes have been saved yet."
+                : string.Join("\n\n", notes.Select((n, i) => $"[{i + 1}] {n.Title}\n{n.Content}"));
+        },
+        "read_notes",
+        "Retrieves all previously saved research notes. " +
+        "Use this to review what you have learned so far before writing a summary."),
+};
+
+// --- Build the agent ---
+const string instructions = """
+    You are a research agent. When given a topic:
+    1. Search the web multiple times to gather diverse information.
+    2. Save important findings as notes using the save_note tool.
+    3. Review your notes using read_notes.
+    4. Provide a comprehensive summary of your research to the user.
+
+    Be thorough — perform at least 2-3 searches from different angles before summarizing.
+    Always save key findings as notes before producing the final summary.
+    """;
+
+var agent = new ChatClientAgent(
+    chatClient,
+    instructions: instructions,
+    name: "ResearchAgent",
+    description: "An agent that researches topics by searching the web and taking notes.",
+    tools: tools);
+
+var runOptions = new ChatClientAgentRunOptions(new ChatOptions
+{
+    Temperature = 0f,
+    MaxOutputTokens = 2048,
+});
+
+// --- Interactive loop ---
+Console.WriteLine("╔══════════════════════════════════════════╗");
+Console.WriteLine("║         🔬 Research Agent                ║");
+Console.WriteLine("║  Enter a topic to research, or 'quit'.   ║");
+Console.WriteLine("╚══════════════════════════════════════════╝");
+Console.WriteLine();
+
+while (true)
+{
+    Console.ForegroundColor = ConsoleColor.Cyan;
+    Console.Write("Research topic> ");
+    Console.ResetColor();
+
+    var topic = Console.ReadLine()?.Trim();
+    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
+        break;
+
+    Console.WriteLine();
+    Console.ForegroundColor = ConsoleColor.Yellow;
+    Console.WriteLine($"Researching: {topic}");
+    Console.ResetColor();
+    Console.WriteLine();
+
+    try
+    {
+        notebook.Clear();
+        var session = await agent.CreateSessionAsync();
+        var response = await agent.RunAsync(
+            $"Research the following topic and provide a detailed summary: {topic}",
+            session,
+            runOptions);
+
+        Console.WriteLine();
+        Console.ForegroundColor = ConsoleColor.Green;
+        Console.WriteLine("═══ Research Summary ═══");
+        Console.ResetColor();
+        Console.WriteLine(response.Text);
+        Console.WriteLine();
+
+        if (notebook.GetAllNotes().Length > 0)
+        {
+            Console.ForegroundColor = ConsoleColor.DarkYellow;
+            Console.WriteLine($"({notebook.GetAllNotes().Length} note(s) collected during research)");
+            Console.ResetColor();
+            Console.WriteLine();
+        }
+    }
+    catch (Exception ex)
+    {
+        Console.ForegroundColor = ConsoleColor.Red;
+        Console.WriteLine($"Error: {ex.Message}");
+        Console.ResetColor();
+        Console.WriteLine();
+    }
+}
+
+Console.WriteLine("Goodbye!");
