+/// <summary>Simulated web search tool that fetches real results via a search API or returns illustrative data.</summary>
+static class WebSearchTool
+{
+    private static readonly HttpClient s_httpClient = new();
+
+    public static async Task<string> SearchAsync(string query)
+    {
+        // Try using a real web search via DuckDuckGo Instant Answer API (no key required).
+        try
+        {
+            var encoded = Uri.EscapeDataString(query);
+            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
+            var json = await s_httpClient.GetStringAsync(url);
+
+            var doc = System.Text.Json.JsonDocument.Parse(json);
+            var results = new StringBuilder();
+
+            var abstractText = doc.RootElement.GetProperty("AbstractText").GetString();
+            var abstractSource = doc.RootElement.GetProperty("AbstractSource").GetString();
+            if (!string.IsNullOrWhiteSpace(abstractText))
+            {
+                results.AppendLine($"Source: {abstractSource}");
+                results.AppendLine(abstractText);
+                results.AppendLine();
+            }
+
+            if (doc.RootElement.TryGetProperty("RelatedTopics", out var topics))
+            {
+                var count = 0;
+                foreach (var item in topics.EnumerateArray())
+                {
+                    if (count >= 5) break;
+                    var text = item.TryGetProperty("Text", out var t) ? t.GetString() : null;
+                    if (!string.IsNullOrWhiteSpace(text))
+                    {
+                        results.AppendLine($"- {text}");
+                        count++;
+                    }
+                }
+            }
+
+            if (results.Length > 0)
+                return results.ToString();
+        }
+        catch
+        {
+            // Fall through to fallback
+        }
+
+        return $"Search results for '{query}': No detailed results available from the web API. " +
+               "Please synthesize information based on your training knowledge about this topic.";
+    }
+}
