+/// <summary>Thread-safe notebook for storing research notes.</summary>
+sealed class ResearchNotebook
+{
+    private readonly List<(string Title, string Content)> _notes = [];
+    private readonly Lock _lock = new();
+
+    public void AddNote(string title, string content)
+    {
+        lock (_lock)
+        {
+            _notes.Add((title, content));
+        }
+    }
+
+    public (string Title, string Content)[] GetAllNotes()
+    {
+        lock (_lock)
+        {
+            return [.. _notes];
+        }
+    }
+
+    public void Clear()
+    {
+        lock (_lock)
+        {
+            _notes.Clear();
+        }
+    }
+}
